:root {
  --color-primary: #d4422f;
  --color-primary-dark: #9b2c1c;
  --color-primary-light: #f5e6e3;
  --color-accent: #ffd700;
  --color-accent-on-dark: #ffd700;
  --color-text: #1a1a1a;
  --color-text-light: #f8f8f8;
  --color-text-muted: #666;
  --color-bg: #ffffff;
  --color-bg-dark: #2a2a2a;
  --color-border: #e0e0e0;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: "Trebuchet MS", Verdana, sans-serif;
  --font-mono: "Courier New", monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

header {
  background-color: var(--color-bg-dark);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

.logo {
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(1.5rem, 5vw, 2rem);
  font-weight: 800;
  color: var(--color-accent);
  text-decoration: none;
  text-shadow: 2px 2px 0 var(--color-primary-dark);
  letter-spacing: 0.05em;
  white-space: nowrap;
  transition: transform 0.2s ease;
}

.logo:hover,
.logo:focus {
  transform: scale(1.05);
  outline: none;
}

header nav {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

header nav a {
  color: var(--color-text-light);
  text-decoration: none;
  font-weight: 600;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  transition: background-color 0.2s ease, color 0.2s ease;
}

header nav a:hover,
header nav a:focus {
  background-color: var(--color-primary-dark);
  color: var(--color-accent);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

footer {
  background-color: var(--color-bg-dark);
  color: var(--color-text-light);
  padding: var(--spacing-xl) 0 var(--spacing-md);
  margin-top: var(--spacing-xl);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.footer-section h3 {
  color: var(--color-accent);
  margin-bottom: var(--spacing-sm);
  font-size: 1.1rem;
}

.footer-section p {
  font-size: 0.9rem;
  line-height: 1.8;
}

.footer-copyright {
  text-align: center;
  font-size: 0.85rem;
  color: var(--color-text-muted);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: var(--spacing-md);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-sans);
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: clamp(2rem, 6vw, 3.5rem);
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
}

h3 {
  font-size: clamp(1.2rem, 3vw, 1.8rem);
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-primary-dark);
  text-decoration: underline;
  transition: color 0.2s ease;
}

a:hover,
a:focus {
  color: var(--color-primary);
  outline: 2px solid var(--color-primary-dark);
  outline-offset: 2px;
}

button,
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  min-height: 44px;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 700;
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: none;
  border-radius: 6px;
  cursor: pointer;
  text-decoration: none;
  transition: background-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.15);
}

button:hover,
.button:hover {
  background-color: var(--color-primary);
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.2);
  transform: translateY(-2px);
}

button:focus,
.button:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active,
.button:active {
  transform: translateY(0);
}

button:disabled {
  background-color: var(--color-text-muted);
  cursor: not-allowed;
  box-shadow: none;
}

form {
  display: grid;
  gap: var(--spacing-md);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="number"],
textarea,
select {
  width: 100%;
  padding: 0.75rem;
  min-height: 44px;
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background-color: var(--color-bg);
  color: var(--color-text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="number"]:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(155, 44, 28, 0.1);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

.card {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
  border-color: var(--color-primary-dark);
}

.card.featured {
  border-color: var(--color-primary-dark);
  background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-bg) 100%);
  box-shadow: 0 4px 12px rgba(212, 66, 47, 0.15);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

section {
  padding: var(--spacing-xl) 0;
}

section:nth-child(even) {
  background-color: #f9f9f9;
}

@media (max-width: 600px) {
  .container {
    padding: 0 var(--spacing-sm);
  }

  header .container {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  header nav {
    width: 100%;
    gap: var(--spacing-sm);
    justify-content: center;
  }

  header nav a {
    padding: 0.4rem 0.8rem;
    font-size: 0.9rem;
  }

  h1 {
    font-size: 1.8rem;
  }

  h2 {
    font-size: 1.4rem;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  button,
  .button {
    width: 100%;
  }

  section {
    padding: var(--spacing-lg) 0;
  }
}

@media (min-width: 601px) {
  header .container {
    justify-content: space-between;
  }

  header nav {
    justify-content: flex-end;
  }

  .grid {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

pages.css:
.hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.hero h1 {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

.hero-subtitle {
  font-size: 1.2rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.section-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-muted);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.price {
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.price-period {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.benefits-list {
  list-style: none;
  margin-bottom: var(--spacing-lg);
  text-align: left;
}

.benefits-list li {
  padding: 0.5rem 0;
  color: var(--color-text);
  line-height: 1.8;
}

.badge {
  display: inline-block;
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: 0.5rem 1rem;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 700;
  margin-bottom: var(--spacing-md);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.index-membership-btn {
  width: 100%;
  min-height: 44px;
}

.testimonials {
  background-color: var(--color-primary-light);
}

.testimonial-text {
  font-size: 1.1rem;
  font-style: italic;
  color: var(--color-text);
  line-height: 1.8;
  margin-bottom: var(--spacing-md);
  border-left: 4px solid var(--color-primary-dark);
  padding-left: var(--spacing-md);
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-primary-dark);
  font-size: 0.95rem;
  margin-bottom: 0;
}

.signup-section {
  background: linear-gradient(135deg, var(--color-bg-dark) 0%, #1a1a1a 100%);
  color: var(--color-text-light);
}

.signup-section h2 {
  color: var(--color-text-light);
}

.signup-intro {
  text-align: center;
  color: var(--color-text-light);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.signup-form {
  max-width: 700px;
  margin: 0 auto;
  background-color: rgba(255, 255, 255, 0.05);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.form-group {
  display: grid;
  gap: 0.5rem;
}

.form-group label {
  color: var(--color-text-light);
}

.form-group input,
.form-group textarea,
.form-group select {
  background-color: rgba(255, 255, 255, 0.95);
  border: 2px solid rgba(255, 255, 255, 0.2);
  color: var(--color-text);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(255, 215, 0, 0.2);
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-md);
}

.form-group.checkbox {
  display: flex;
  flex-direction: row;
  gap: var(--spacing-sm);
  align-items: flex-start;
  margin-top: var(--spacing-md);
}

.form-group.checkbox input[type="checkbox"] {
  width: auto;
  min-height: 44px;
  min-width: 44px;
  margin-top: 0;
  cursor: pointer;
  flex-shrink: 0;
}

.label-inline {
  margin-bottom: 0;
  font-weight: 400;
  color: var(--color-text-light);
  line-height: 1.5;
  padding-top: 0.5rem;
}

.button-large {
  width: 100%;
  font-size: 1.1rem;
  min-height: 48px;
  margin-top: var(--spacing-md);
}

@media (max-width: 600px) {
  .hero {
    padding: var(--spacing-lg) 0;
  }

  .hero-subtitle {
    font-size: 1rem;
    margin-bottom: var(--spacing-md);
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .signup-form {
    padding: var(--spacing-md);
  }

  .price {
    font-size: 1.5rem;
  }

  .testimonial-text {
    font-size: 1rem;
    padding-left: var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .hero {
    padding: 5rem 0;
  }

  .hero-subtitle {
    font-size: 1.3rem;
  }

  .signup-form {
    padding: var(--spacing-xl);
  }
}

