  color: var(--color-text-light);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.hero h1 {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

.hero-subtitle {
  font-size: 1.2rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.section-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-muted);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.price {
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.price-period {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.benefits-list {
  list-style: none;
  margin-bottom: var(--spacing-lg);
  text-align: left;
}

.benefits-list li {
  padding: 0.5rem 0;
  color: var(--color-text);
  line-height: 1.8;
}

.badge {
  display: inline-block;
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: 0.5rem 1rem;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 700;
  margin-bottom: var(--spacing-md);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.index-membership-btn {
  width: 100%;
  min-height: 44px;
}

.testimonials {
  background-color: var(--color-primary-light);
}

.testimonial-text {
  font-size: 1.1rem;
  font-style: italic;
  color: var(--color-text);
  line-height: 1.8;
  margin-bottom: var(--spacing-md);
  border-left: 4px solid var(--color-primary-dark);
  padding-left: var(--spacing-md);
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-primary-dark);
  font-size: 0.95rem;
  margin-bottom: 0;
}

.signup-section {
  background: linear-gradient(135deg, var(--color-bg-dark) 0%, #1a1a1a 100%);
  color: var(--color-text-light);
}

.signup-section h2 {
  color: var(--color-text-light);
}

.signup-intro {
  text-align: center;
  color: var(--color-text-light);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.signup-form {
  max-width: 700px;
  margin: 0 auto;
  background-color: rgba(255, 255, 255, 0.05);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.form-group {
  display: grid;
  gap: 0.5rem;
}

.form-group label {
  color: var(--color-text-light);
}

.form-group input,
.form-group textarea,
.form-group select {
  background-color: rgba(255, 255, 255, 0.95);
  border: 2px solid rgba(255, 255, 255, 0.2);
  color: var(--color-text);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(255, 215, 0, 0.2);
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-md);
}

.form-group.checkbox {
  display: flex;
  flex-direction: row;
  gap: var(--spacing-sm);
  align-items: flex-start;
  margin-top: var(--spacing-md);
}

.form-group.checkbox input[type="checkbox"] {
  width: auto;
  min-height: 44px;
  min-width: 44px;
  margin-top: 0;
  cursor: pointer;
  flex-shrink: 0;
}

.label-inline {
  margin-bottom: 0;
  font-weight: 400;
  color: var(--color-text-light);
  line-height: 1.5;
  padding-top: 0.5rem;
}

.button-large {
  width: 100%;
  font-size: 1.1rem;
  min-height: 48px;
  margin-top: var(--spacing-md);
}

@media (max-width: 600px) {
  .hero {
    padding: var(--spacing-lg) 0;
  }

  .hero-subtitle {
    font-size: 1rem;
    margin-bottom: var(--spacing-md);
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .signup-form {
    padding: var(--spacing-md);
  }

  .price {
    font-size: 1.5rem;
  }

  .testimonial-text {
    font-size: 1rem;
    padding-left: var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .hero {
    padding: 5rem 0;
  }

  .hero-subtitle {
    font-size: 1.3rem;
  }

  .signup-form {
    padding: var(--spacing-xl);
  }
}
